(()=>{
'use strict';
const root=document.getElementById('infra-observer'),content=root.querySelector('#io-content'),feedback=root.querySelector('#io-feedback'),inv=window.InfraInventory,C=window.InfraOpsCore;
const {esc,badge,table,box,stats,facts,field,number,validHost}=inv.helpers;
const anchor=Date.parse('2026-10-18T00:40:00+08:00'),day=86400000,db=()=>inv.data();
const blank={version:1,assets:{},domains:{},rules:{},events:[],savedSearches:[],policies:{}};let state=structuredClone(blank),storageOK=true;
try{const stored=JSON.parse(localStorage.getItem('infrascope.ops.v1'));if(stored?.version===1)state={...blank,...stored};}catch{storageOK=false;}
let page='alerts',selectedEvent=null,alertQuery='',alertKind='全部',alertSeverity='全部',alertState='全部',alertPeriod='全部',historyTarget='s1',historyIface='eth0',historyRange='24h',historyFrom=anchor-day,historyTo=anchor,historyError='';
const btn=(label,action,id='',kind='',cls='')=>`<button type="button" data-op="${action}" data-id="${esc(id)}" data-kind="${esc(kind)}" class="${cls}">${label}</button>`;
const small=t=>`<span class="iv-small">${esc(t)}</span>`;
const dt=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未知';
const short=t=>new Date(t).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const local=t=>new Date(t+8*3600000).toISOString().slice(0,16);
const GiB=n=>Number.isFinite(n)?(n/1073741824).toFixed(2)+' GiB':'—';
const uptime=(boot,at)=>boot&&at?C.duration(at-boot):'未知';
function persist(message=''){try{localStorage.setItem('infrascope.ops.v1',JSON.stringify(state));storageOK=true;}catch{storageOK=false;}if(message)feedback.textContent=message+(storageOK?' 已保存到当前浏览器。':' 浏览器存储不可用，本次会话保留。');}
function asset(id){const x=[...db().servers,...db().containers,...db().switches].find(a=>a.id===id);if(!x)return null;if(state.assets[id])return state.assets[id];const seeded=/^[scw]\d+$/.test(id),unknown=/待|过期/.test(x.state),at=anchor;let data={sampledAt:seeded?at:null,bootAt:seeded?at-(id==='c3'?120000:(id==='s2'?18:38)*day+5*3600000):null,onlineSince:seeded?at-12*day-7*3600000:null,status:unknown?'未知 / 采集缺失':x.state.includes('异常')?'运行异常':/告警|预警|缺纸/.test(x.state)?'在线 · '+x.state:'在线',reason:seeded?'最近心跳与 Collector 观测（模拟）':'等待 Agent 上报',stateAt:at-((unknown?87:0)*1000),discovered:false,interfaces:[],disks:[],ports:[],monitor:[],mode:'auto'};
if(!seeded||/^待/.test(x.state)){data.status='待接入';data.bootAt=null;data.onlineSince=null;data.sampledAt=null;}
if(seeded&&!/待/.test(x.state)&&(x.os==='Linux'||x.os==='Windows')){data=discoverData(x,x.os,seeded?at:Date.now(),data);if(unknown){data.status='未知 / 采集缺失';data.onlineSince=null;data.reason='心跳过期；不能据此确认关机或断网';}}
state.assets[id]=data;return data;}
function discoverData(x,os,at,previous={}){const win=os==='Windows',pve=x.kind==='虚拟化节点',nic=pve?'vmbr0':win?'Ethernet':'eth0',second=pve?'eno1':win?'Ethernet 2':'eth1';const interfaces=[{id:nic,name:nic,type:pve?'bridge':'physical',up:true,ip:x.ip,speed:1000,routes:[{family:'IPv4',default:true,metric:100}],mac:'02:42:AC:14:01:11'},{id:second,name:second,type:'physical',up:true,ip:win?'10.40.1.20':'10.30.1.11',speed:1000,routes:[],mac:'02:42:AC:14:01:12'},{id:pve?'eno2':win?'vEthernet':'docker0',name:pve?'eno2':win?'vEthernet':'docker0',type:pve?'physical':'bridge',up:true,ip:'172.17.0.1',speed:null,routes:[],mac:'02:42:AC:11:00:01'}];return {...previous,discovered:true,os,version:win?'Windows Server 2022':'Ubuntu 24.04 LTS',sampledAt:at,bootAt:previous.bootAt||at-38*day-5*3600000,onlineSince:previous.onlineSince||at-12*day-7*3600000,status:'在线',reason:'Rust Agent 资产上报 + 心跳（模拟）',stateAt:at,interfaces,monitor:C.egress(interfaces),mode:'auto',disks:[{mount:win?'C:':'/',fs:win?'NTFS':'ext4',total:128,used:72,available:56},{mount:win?'D:':'/data',fs:win?'NTFS':'xfs',total:1024,used:738,available:286}],ports:[{port:win?3389:22,protocol:'TCP',process:win?'TermService':'sshd',bind:'0.0.0.0',exposure:'主机监听；外部可达性未检测'},{port:443,protocol:'TCP',process:win?'HTTP.sys':'nginx',bind:'0.0.0.0',exposure:'主机监听；需配置服务探测'},{port:8080,protocol:'TCP',process:'office-api',bind:'127.0.0.1',exposure:'仅本机回环'}]};}
function ruleButton(kind,x){if(kind==='containers'){kind='dockerGroups';x={...x,id:window.InfraWorkspaceCore?.groupId(x)||x.name};}return ' '+btn('告警规则','rules',x.id,kind,'link-button');}
function rowStatus(kind,x){if(kind==='services'){const o=state.assets['service:'+x.id];return badge(o?.status||x.state)+small('连续可用 '+(o?.availableSince?uptime(o.availableSince,o.at):x.state==='正常'&&x.checked&&/^v[123]$/.test(x.id)?'12 天 7 小时（快照）':'未知'));}const a=asset(x.id);if(!a)return '';const running=/^在线|^运行异常/.test(a.status);return badge(a.status)+(a.sampledAt?small((running?'已运行 ':'最后已知运行 ')+uptime(a.bootAt,a.sampledAt))+small(running?'连续在线 '+uptime(a.onlineSince,a.sampledAt):a.reason):small('等待有效采样'));}
function detailTop(kind,x){if(kind==='services')return serviceExtra(x);const a=asset(x.id);if(!a)return '';return `<section class="box op-status-strip"><div><div class="iv-kicker">LIFECYCLE / OBSERVED STATUS</div>${badge(a.status)}${small(a.reason)}</div><div><label>${/^在线|^运行异常/.test(a.status)?'本次启动已运行':'最后已知运行时长'}</label><strong>${uptime(a.bootAt,a.sampledAt)}</strong>${small('启动时间 '+dt(a.bootAt))}</div><div><label>连续在线（观测）</label><strong>${uptime(a.onlineSince,a.sampledAt)}</strong>${small('有效上报时 '+dt(a.sampledAt))}</div><div>${btn('单对象告警规则','rules',x.id,kind)}${btn('关联告警','object-alerts',x.name)}</div></section>`;}
function detailBottom(kind,x){if(kind==='services'||kind==='containers'||kind==='switches')return '';if(!['Linux','Windows','待识别'].includes(x.os))return '';const a=asset(x.id),can=a.discovered;return `<div class="iv-summary"><section class="box"><div class="panel-head"><div><h3>Agent 自动发现</h3><small>操作系统 · 磁盘 · 所有网卡 · 监听端口</small></div>${badge(can?'已发现（模拟）':'等待发现')}</div><div class="iv-probe-actions"><label>示例系统<select id="op-profile"><option ${x.os==='Windows'?'':'selected'}>Linux</option><option ${x.os==='Windows'?'selected':''}>Windows</option></select></label>${btn('模拟 Agent 上报','discover',x.id,'','main')}</div><p class="iv-note">只演示采集结果，不安装 Agent、不扫描设备。新增对象首次模拟上报从当前时刻开始记录。</p>${facts([['系统类型',can?a.os+' / '+a.version:'等待上报'],['发现网卡数',can?a.interfaces.length+' 张':'未知'],['磁盘 / 文件系统',can?a.disks.length+' 个':'未知'],['资产更新时间',dt(a.sampledAt)]])}</section>${box('故障状态与证据',`<div class="iv-probe-actions"><label>演示场景<select id="op-scenario"><option value="online">在线</option><option value="lost">心跳失联 · 原因未知</option><option value="network">链路中断 · 带外证据</option><option value="off">已关机 · 电源状态证据</option></select></label>${btn('切换模拟状态','scenario',x.id)}</div><div class="iv-callout">失联：心跳缺失；断网：链路证据 + 带外确认电源开启；关机：虚拟化平台或带外电源状态确认。主机、服务与采集质量各自判定。</div>`)}</div>`+(can?box('自动发现的磁盘空间',table(['挂载点','文件系统','总容量','已用','可用','使用率'],a.disks.map(d=>[esc(d.mount),esc(d.fs),d.total+' GiB',d.used+' GiB',d.available+' GiB',`${(d.used/d.total*100).toFixed(1)}%<div class="tiny-meter"><i style="width:${d.used/d.total*100}%"></i></div>`])),'iv-bottom')+box('网络接口与出口选择',`<div class="op-inline"><label>监控策略<select id="op-egress-mode"><option value="auto" ${a.mode==='auto'?'selected':''}>自动跟随默认路由候选</option><option value="manual" ${a.mode==='manual'?'selected':''}>手动选择接口</option></select></label>${btn('保存网卡监控','save-ifaces',x.id,'','main')}${btn('流量回溯 ↗','traffic',x.id,a.monitor[0]||a.interfaces[0].id)}</div>`+table(['监控','接口 / 类型','IP / 链路','默认路由','出口判断','操作'],a.interfaces.map(n=>[`<input type="checkbox" data-op-nic="${esc(n.id)}" ${a.monitor.includes(n.id)?'checked':''} ${a.mode==='auto'?'disabled':''} aria-label="监控 ${esc(n.name)}">`,esc(n.name)+small(n.type),esc(n.ip)+small(n.speed?n.speed+' Mbps':'链路速率未知'),n.routes.length?n.routes.map(r=>`${r.family} / metric ${r.metric}`).join('<br>'):'无',C.egress(a.interfaces).includes(n.id)?badge('出口候选'):small('非默认出口'),btn('历史流量','traffic',x.id,n.id)]))+`<div class="iv-callout">默认路由只代表出口候选，NAT 后的公网访问仍可能经过内网 IP。多出口、IPv4/IPv6、VPN 和策略路由需要按目标验证。网桥 / Bond 与物理口不重复汇总。</div>`,'iv-bottom')+box('自动发现的监听端口',table(['端口','协议','进程 / 绑定地址','可达性','操作'],a.ports.map(p=>[p.port,esc(p.protocol),esc(p.process)+small(p.bind),small(p.exposure),btn('添加服务监控','from-port',x.id,String(p.port))])),'iv-bottom'):'');}
function serviceExtra(x){const o=state.assets['service:'+x.id],since=o?.availableSince||(x.state==='正常'&&x.checked&&/^v[123]$/.test(x.id)?anchor-12*day-7*3600000:null);return box('服务运行状态与延迟',`<div class="op-status-strip"><div>${badge(o?.status||x.state)}${small('业务可用性与主机在线状态分开')}</div><div><label>连续可用（观测）</label><strong>${uptime(since,o?.at||anchor)}</strong>${small('由探测连续性统计，不是进程启动时长')}</div><div><label>响应延迟</label><strong>${o?.latency??x.latency??'—'} ms</strong>${small('正常返回也可能响应慢')}</div><div>${ruleButton('services',x)} ${btn('关联告警','object-alerts',x.name)}</div></div><div class="iv-probe-actions"><label>扩展示例<select id="op-service-scenario"><option value="slow">响应慢 · 1500 ms</option><option value="down">端口不可达 / 拒绝连接</option><option value="ok">恢复正常 · 43 ms</option></select></label>${btn('模拟状态','service-state',x.id)}${btn('查看域名监控','domains',x.id)}</div>`,'iv-bottom');}
function onConfigured(kind,x){delete state.assets[x.id];delete state.assets['service:'+x.id];if(kind==='services')delete state.domains['svc-'+x.id];persist();}
function onProbe(x){Object.values(state.rules).filter(r=>r.kind==='services'&&r.target===x.id).forEach(r=>evaluateRule(r.key,r.metric==='latency'?x.latency:((x.protocol==='TCP'?x.code==='连接成功':String(x.code)===String(x.expected))?0:1)));const o=state.assets['service:'+x.id]||{};state.assets['service:'+x.id]={...o,status:x.state,at:Date.now(),latency:x.latency,availableSince:x.state==='正常'?(o.availableSince||Date.now()):null};persist();}
function names(kind,id){if(kind==='dockerGroups')return window.InfraWorkspace?.group(id);if(kind==='domains')return domainList().find(d=>d.id===id);if(kind==='traffic'){const [sid,nic]=id.split('/');const s=db().servers.find(s=>s.id===sid);return {id,name:(s?.name||sid)+' / '+nic,business:s?.business||'网络'};}return db()[{devices:'servers',containers:'containers',services:'services',switches:'switches'}[kind]]?.find(x=>x.id===id);}
function metrics(kind){if(kind==='dockerGroups')return [['restart','组内 10 分钟重启总数','次','gt',3,1],['unhealthy','组内异常实例数','个','gt',0,1]];return kind==='devices'?[['heartbeat','心跳缺失','秒','gt',30,10],['cpu','CPU 使用率','%','gt',90,75],['disk','磁盘可用比例','%','lt',10,15]]:kind==='services'?[['latency','响应延迟','ms','gt',500,300],['failure','探测失败','0=正常 / 1=失败','gt',0,1]]:kind==='domains'?[['dns','DNS 失败','0=正常 / 1=失败','gt',0,1],['tls','证书剩余天数','天','lt',14,21],['latency','HTTP 响应延迟','ms','gt',500,300]]:kind==='traffic'?[['rx','接收速率','Mbps','gt',300,200],['tx','发送速率','Mbps','gt',200,150]]:kind==='containers'?[['restart','10 分钟重启数','次','gt',3,1]]:[['discard','端口丢包率','%','gt',1,.5]];}
function kindLabel(k){return {dockerGroups:'Docker 分组',devices:'设备',services:'服务',containers:'容器实例',domains:'域名',traffic:'流量',switches:'交换机'}[k]||k;}
function newRule(kind,id,metric){const m=metrics(kind).find(m=>m[0]===metric)||metrics(kind)[0],x=names(kind,id);return {key:kind+':'+id+':'+m[0],kind,target:id,targetName:x?.name||id,business:x?.business||'未分配',metric:m[0],label:m[1],unit:m[2],op:m[3],threshold:m[4],recovery:m[5],fail:3,recover:2,severity:'警告',channel:'企业微信 + 邮件',receiver:'业务值班组',repeat:30,enabled:true,runtime:{bad:0,good:0,firing:false,state:'未评估'}};}
function dialog(title,body,submitText='保存',callback){root.querySelector('#op-dialog')?.remove();const d=document.createElement('dialog');d.id='op-dialog';d.className='iv-dialog';d.setAttribute('aria-labelledby','op-dialog-title');d.innerHTML=`<form><header><div><div class="iv-kicker">OBSERVABILITY CONFIGURATION</div><h2 id="op-dialog-title">${esc(title)}</h2></div>${btn('×','close')}</header><div class="iv-form-body">${body}<div class="iv-error" role="alert"></div></div><footer><span class="muted">Demo 配置 · 不发送通知</span>${btn('取消','close')}${callback?`<button type="submit" class="main">${submitText}</button>`:''}</footer></form>`;root.append(d);d.showModal();if(callback)d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();callback(Object.fromEntries(new FormData(e.target)),d);});return d;}
function openRules(kind,id,metric){const x=names(kind,id);if(!x)return;const r=state.rules[kind+':'+id+':'+(metric||metrics(kind)[0][0])]||newRule(kind,id,metric);const related=Object.values(state.rules).filter(v=>v.kind===kind&&v.target===id);const d=dialog(x.name+' · 告警规则',`<div class="iv-callout">每个对象可以配置多个指标规则。连续异常才触发，恢复单独判断；确认告警不会解除故障。</div><div class="iv-form-grid" style="margin-top:18px">${field('监控指标','metric',r.metric,{options:metrics(kind).map(m=>[m[0],m[1]+' / '+m[2]])})}${field('规则状态','enabled',r.enabled?'true':'false',{options:[['true','启用'],['false','禁用']]})}${number((r.op==='lt'?'低于':'高于')+'触发阈值（'+r.unit+'）','threshold',r.threshold,0,1000000)}${number((r.op==='lt'?'高于':'低于')+'恢复阈值','recovery',r.recovery,0,1000000)}${number('连续异常次数','fail',r.fail,1,30)}${number('连续恢复次数','recover',r.recover,1,30)}${field('告警级别','severity',r.severity,{options:['警告','严重','提示']})}${field('通知渠道','channel',r.channel,{options:['企业微信 + 邮件','企业微信','邮件 SMTP','钉钉','飞书']})}${field('接收组','receiver',r.receiver)}${number('重复提醒间隔（分钟）','repeat',r.repeat,1,1440)}</div><div class="iv-callout">通知渠道使用“通知配置”中的连接信息。此处配置路由和规则，不发出真实企业通知或邮件。</div>${related.length?'<h3 style="margin-top:20px">该对象已保存的规则</h3>'+table(['指标','触发 / 恢复','状态','操作'],related.map(q=>[esc(q.label),q.threshold+' / '+q.recovery,badge(q.runtime?.state||'未评估'),btn('模拟评估','evaluate',q.key)])):''}`,'保存规则',(values,d)=>{const q=newRule(kind,id,values.metric);for(const k of ['threshold','recovery','fail','recover','repeat'])values[k]=Number(values[k]);if((q.op==='gt'&&values.recovery>values.threshold&&q.metric!=='failure'&&q.metric!=='dns'&&q.metric!=='unhealthy')||(q.op==='lt'&&values.recovery<values.threshold)){d.querySelector('.iv-error').textContent='恢复阈值需位于安全侧：上限告警的恢复值应更低，下限告警应更高。';return;}state.rules[q.key]={...q,...values,enabled:values.enabled==='true'};d.close();persist('规则已保存，可在告警看板的规则列表中模拟评估。');});d.querySelector('[name="metric"]').addEventListener('change',e=>{d.close();openRules(kind,id,e.target.value);});d.querySelectorAll('input[name="threshold"],input[name="recovery"]').forEach(el=>el.step='any');}
function evaluateRule(key,value){const r=state.rules[key];if(!r||!r.enabled)return;r.runtime=C.evaluate(r,value,Date.now());const existing=state.events.find(e=>e.rule===key&&!e.resolved);if(r.runtime.firing&&!existing){state.events.unshift({id:'evt-'+Date.now(),rule:key,kind:r.kind,target:r.target,targetName:r.targetName,business:r.business,severity:r.severity,title:r.label+'超过告警条件',value:value+' '+r.unit,at:Date.now(),updated:Date.now(),resolved:null,ack:false,silencedUntil:null,channel:r.channel,receiver:r.receiver,delivery:'模拟通知任务 · 未发送',timeline:[{at:Date.now(),text:'达到连续异常阈值，创建告警事件'}]});}else if(existing){existing.updated=Date.now();existing.value=value+' '+r.unit;if(!r.runtime.firing&&r.runtime.state==='正常'){existing.resolved=Date.now();existing.timeline.push({at:Date.now(),text:'有效样本达到恢复条件，事件恢复'});}}persist('模拟评估：'+r.runtime.state+'；异常 '+r.runtime.bad+' 次 / 恢复 '+r.runtime.good+' 次。');}
function openEvaluate(key){const r=state.rules[key];if(!r)return;const d=dialog(r.targetName+' · 模拟评估',`<div class="iv-callout">${esc(r.label)} ${r.op==='gt'?'高于':'低于'} ${r.threshold} ${esc(r.unit)}，连续 ${r.fail} 次触发；连续 ${r.recover} 次恢复。</div><div class="iv-form-grid" style="margin-top:18px">${number('输入观测值（'+r.unit+'）','value',r.threshold+(r.op==='gt'?1:-1),0,10000000)}</div><div class="op-evaluation">${badge(r.runtime?.state||'未评估')}${small('可以连续点击，观察待确认 → 告警 → 恢复')}</div>`,'评估一次',(v,d)=>{evaluateRule(key,Number(v.value));d.querySelector('.op-evaluation').innerHTML=badge(r.runtime.state)+small(`连续异常 ${r.runtime.bad} / 连续恢复 ${r.runtime.good}`);if(page==='alerts'&&content.querySelector('#op-alert-results'))renderAlerts();});d.querySelector('[name="value"]').step='any';}
function pageHead(title,subtitle,actions=''){content.dataset.studioTitle=title;root.querySelector('#studio-breadcrumb').textContent=title;root.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));try{history.replaceState(null,'','#'+page);}catch{}return `<div class="page-heading"><div><div class="iv-kicker">OBSERVABILITY / INVESTIGATION</div><h2>${esc(title)}</h2><div class="muted">${esc(subtitle)}</div></div><div class="page-actions">${actions}</div></div><div class="iv-banner"><i class="iv-orb"></i><strong>交互演示</strong> 所有采样、故障、探测及投递均为模拟 · 不连接真实设备<span>${storageOK?'配置与事件在当前浏览器保存':'存储不可用 / 本次会话'}</span></div>`;}
function render(p){page=p;selectedEvent=null;if(p==='alerts')renderAlerts();if(p==='domains')renderDomains();if(p==='traffic')renderTraffic();}
function filteredEvents(){return state.events.filter(e=>(alertKind==='全部'||e.kind===alertKind)&&(alertSeverity==='全部'||e.severity===alertSeverity)&&(alertState==='全部'||(alertState==='告警中'&&!e.resolved)||(alertState==='已恢复'&&e.resolved)||(alertState==='未确认'&&!e.ack)||(alertState==='已确认'&&e.ack)||(alertState==='静默中'&&e.silencedUntil>Date.now()))&&(alertPeriod==='全部'||e.at>=Date.now()-Number(alertPeriod)*3600000)&&JSON.stringify(e).toLowerCase().includes(alertQuery.toLowerCase()));}
const opts=(a,val)=>a.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`;}).join('');
function renderAlerts(){const active=state.events.filter(e=>!e.resolved);content.innerHTML=pageHead('告警搜索看板','按设备、业务、域名、端口、网卡和时间追踪同一个事件',btn('保存当前筛选','save-search')+btn('通知渠道 ↗','notify'))+stats([['告警中',active.length,'故障状态独立于确认状态'],['严重告警',active.filter(e=>e.severity==='严重').length,'优先排查业务影响'],['已恢复',state.events.filter(e=>e.resolved).length,'保留故障及恢复时间'],['通知路由',new Set(state.events.map(e=>e.channel)).size,'仅模拟记录，不真实发送']])+`<section class="box"><div class="op-alert-filter"><label>搜索<input id="op-alert-search" value="${esc(alertQuery)}" placeholder="设备、域名、业务、网卡或规则"></label><label>类别<select id="op-alert-kind">${opts(['全部',...['devices','services','domains','traffic','dockerGroups','switches'].map(k=>[k,kindLabel(k)])],alertKind)}</select></label><label>级别<select id="op-alert-severity">${opts(['全部','严重','警告','提示'],alertSeverity)}</select></label><label>状态<select id="op-alert-state">${opts(['全部','告警中','已恢复','未确认','已确认','静默中'],alertState)}</select></label><label>时间<select id="op-alert-period">${opts([['全部','全部记录'],['1','最近 1 小时'],['24','最近 24 小时'],['168','最近 7 天']],alertPeriod)}</select></label>${btn('清空筛选','reset-filter')}</div>${state.savedSearches.length?`<div class="op-saved">已保存视图 ${state.savedSearches.map((s,i)=>btn(esc(s.label),'load-search',String(i))).join('')}</div>`:''}<div id="op-alert-results"></div></section><div class="iv-bottom">${box('单对象告警规则',table(['对象 / 类别','指标 / 条件','触发 / 恢复','通知路由','规则状态','操作'],Object.values(state.rules).map(r=>[esc(r.targetName)+small(kindLabel(r.kind)),esc(r.label)+small((r.op==='gt'?'> ':'< ')+r.threshold+' '+r.unit),`${r.fail} 次 / ${r.recover} 次`,esc(r.channel)+small(r.receiver),badge(r.enabled?(r.runtime?.state||'未评估'):'已禁用'),btn('编辑','rules',r.target,r.kind)+btn('模拟评估','evaluate',r.key)])))}</div><div class="iv-callout">单条告警包含证据、规则、生命周期和通知记录。确认只表示有人接手；静默只暂停模拟通知，故障是否恢复由新样本判断。</div>`;paintEvents();}
function paintEvents(){const list=filteredEvents();content.querySelector('#op-alert-results').innerHTML=table(['级别 / 状态','事件 / 对象','业务 / 类别','首次 / 最近变化（CST）','处理 / 通知','操作'],list.map(e=>[badge(e.severity)+small(e.resolved?'已恢复':'告警中'),btn(esc(e.title),'event',e.id,'','link-button')+small(e.targetName),esc(e.business)+small(kindLabel(e.kind)),dt(e.at)+small(dt(e.updated)),badge(e.ack?'已确认':'未确认')+small(e.silencedUntil>Date.now()?'静默至 '+dt(e.silencedUntil):e.delivery),btn('详情','event',e.id)+(e.kind==='traffic'?btn('流量回溯','event-traffic',e.id):'')]))+`<div class="table-footer"><span>${list.length} / ${state.events.length} 条事件</span><span>记录保存在本浏览器；支持搜索已恢复事件</span></div>`;}
function eventDetail(id){selectedEvent=id;const e=state.events.find(e=>e.id===id);if(!e)return;content.innerHTML=pageHead('告警事件详情',e.targetName+' / '+e.title,btn('← 返回看板','alerts'))+stats([['故障状态',badge(e.resolved?'已恢复':'告警中'),e.resolved?'恢复于 '+dt(e.resolved):'最后变化 '+dt(e.updated)],['持续时间',C.duration((e.resolved||Date.now())-e.at),'按事件开始 / 恢复时间'],['处理状态',badge(e.ack?'已确认':'未确认'),'确认不等于恢复'],['通知状态',e.silencedUntil>Date.now()?'静默中':'模拟任务','没有发送真实消息']])+`<div class="iv-summary">${box('证据与归属',facts([['事件',e.title],['对象',e.targetName],['类别 / 业务',kindLabel(e.kind)+' / '+e.business],['最新观测',e.value],['首次发生',dt(e.at)],['恢复时间',e.resolved?dt(e.resolved):'尚未恢复']])+`<div class="iv-probe-actions">${btn(e.ack?'已确认':'确认告警','ack',id)}${btn(e.silencedUntil>Date.now()?'取消静默':'静默 30 分钟','silence',id)}${e.kind==='traffic'?btn('回看发生前后流量','event-traffic',id,'','main'):''}${state.rules[e.rule]?btn('编辑这条规则','rules',e.target,e.kind):''}</div>`)}${box('通知路由与事件时间线',facts([['渠道',e.channel],['接收组',e.receiver],['投递结果',e.delivery],['升级策略','未确认 10 分钟 → 邮件备份组（示意）']])+`<div class="op-timeline">${e.timeline.map(t=>`<div><time>${dt(t.at)}</time><span>${esc(t.text)}</span></div>`).join('')}</div>`)}</div>`;}
function domainList(){const fromServices=db().services.filter(s=>s.domain&&!inv.helpers.isIP(s.domain)).map(s=>{const id='svc-'+s.id;return {id,name:s.domain,business:s.business,service:s.id,protocol:s.protocol==='TCP'?'DNS':s.protocol,port:s.port,path:s.path||'/',expected:s.expected||200,interval:60,timeout:5,collector:s.collector,...(state.domains[id]||{})};});return [...fromServices,...Object.values(state.domains).filter(d=>!d.id.startsWith('svc-'))];}
function domainObservation(d){if(d.observation)return d.observation;if(d.service&&db().services.find(s=>s.id===d.service)?.checked&&/^v[1-4]$/.test(d.service))return {state:d.id==='svc-v1'?'证书即将到期':'正常',dns:'解析成功',ips:['192.0.2.10'],ttl:300,dnsMs:8,http:d.protocol==='DNS'?null:200,httpMs:d.protocol==='DNS'?null:43,certDays:d.protocol==='HTTPS'?12:null,certName:d.name,chain:d.protocol==='HTTPS'?'匹配 / 信任链通过（模拟）':'不适用',at:anchor,history:[]};return {state:'未检测',dns:'未知',ips:[],ttl:null,dnsMs:null,http:null,httpMs:null,certDays:null,chain:'未知',at:null,history:[]};}
function renderDomains(){const domains=domainList();content.innerHTML=pageHead('域名监控','DNS 解析、HTTP 可用性、证书与响应延迟分别观察',btn('+ 添加域名监控','add-domain','','','main'))+stats([['域名监控项',domains.length,'服务域名自动关联，可独立添加'],['DNS 异常',domains.filter(d=>domainObservation(d).dns==='解析失败').length,'不把解析失败误判为服务关机'],['证书需关注',domains.filter(d=>domainObservation(d).certDays!=null&&domainObservation(d).certDays<14).length,'HTTPS 证书剩余天数'],['未检测',domains.filter(d=>domainObservation(d).state==='未检测').length,'配置后等待有效探测']])+box('监控目标',table(['域名 / 业务','协议 / 端口','DNS','HTTP / 延迟','TLS 证书','状态 / 操作'],domains.map(d=>{const o=domainObservation(d);return [btn(esc(d.name),'domain',d.id,'','link-button')+small(d.business),esc(d.protocol)+(d.protocol==='DNS'?'':' / '+d.port)+small(d.path),esc(o.dns)+small(o.ips.join(', ')||'—'),o.http==null?'—':o.http+small(o.httpMs+' ms'),o.certDays==null?'不适用 / 未知':o.certDays+' 天'+small('证书有效期，不代表域名注册到期'),badge(o.state)+' '+btn('详情','domain',d.id)+ruleButton('domains',d)];})))+`<div class="iv-callout">探测来自配置的 Collector；内网域名在内网解析。DNS、TCP、TLS、HTTP 需要分别记录失败阶段。此处的证书到期与域名注册到期不是同一概念。</div>`;}
function domainDetail(id){const d=domainList().find(d=>d.id===id);if(!d)return;const o=domainObservation(d);content.innerHTML=pageHead(d.name,'域名 / '+d.business+' / '+d.collector,btn('← 返回域名列表','domains')+btn('编辑','edit-domain',id))+`<div class="iv-summary">${box('解析与证书',facts([['当前状态',o.state],['最近检测',dt(o.at)],['DNS 解析',o.dns],['解析 IP',o.ips.join(', ')||'未知'],['DNS 耗时 / TTL',(o.dnsMs??'—')+' ms / '+(o.ttl??'—')+'s'],['证书剩余时间',o.certDays==null?'不适用 / 未知':o.certDays+' 天'],['主机名 / 信任链',o.chain],['探测周期',d.interval+'s']]))}${box('业务入口检测',facts([['探测地址',d.protocol==='DNS'?d.name:d.protocol.toLowerCase()+'://'+d.name+':'+d.port+d.path],['HTTP 结果',o.http??'尚未检测 / 不适用'],['响应时间',o.httpMs==null?'—':o.httpMs+' ms'],['单次超时',d.timeout+'s']])+`<div class="iv-probe-actions"><label>模拟结果<select id="op-domain-result"><option value="ok">全部正常</option><option value="dns">DNS 解析失败</option>${d.protocol==='HTTPS'?'<option value="cert">证书剩余 7 天</option>':''}${d.protocol!=='DNS'?'<option value="slow">HTTP 延迟 1500 ms</option>':''}</select></label>${btn('运行模拟检测','domain-probe',id,'','main')}</div><div style="margin-top:15px">${ruleButton('domains',d)} ${btn('搜索关联告警','object-alerts',d.name)}</div>`)}</div>`+box('检测历史',table(['时间 CST','DNS','HTTP','延迟','证书剩余','结果'],o.history?.length?o.history.map(h=>[dt(h.at),esc(h.dns),h.http??'—',h.httpMs==null?'—':h.httpMs+' ms',h.certDays==null?'—':h.certDays+' 天',badge(h.state)]):[[dt(o.at),esc(o.dns),o.http??'—',o.httpMs==null?'—':o.httpMs+' ms',o.certDays==null?'—':o.certDays+' 天',badge(o.state)]]));}
function domainForm(id){const current=domainList().find(d=>d.id===id),d=current||{protocol:'HTTPS',port:443,path:'/',expected:200,interval:60,timeout:5,collector:'机房 A · collector-01'};dialog(current?'编辑域名监控':'添加域名监控',`<div class="iv-form-grid">${field('域名（不含协议）','name',d.name,{placeholder:'portal.example.com'})}${field('业务归属','business',d.business)}${field('检查类型','protocol',d.protocol,{options:['HTTPS','HTTP','DNS']})}${number('HTTP(S) 端口','port',d.port)}${field('请求路径（DNS 模式忽略）','path',d.path)}${number('预期 HTTP 状态码','expected',d.expected,100,599)}${number('检测间隔（秒）','interval',d.interval,10,3600)}${number('超时（秒）','timeout',d.timeout,1,300)}${field('探测节点','collector',d.collector,{full:true,options:['机房 A · collector-01','办公区 · collector-02','异地机房 · collector-03']})}</div><p class="iv-note">DNS 模式仅检测解析。HTTPS 额外展示主机名、信任链和证书有效期；不查询域名注册到期时间。</p>`,'保存监控',(v,modal)=>{Object.keys(v).forEach(k=>v[k]=v[k].trim());if(!validHost(v.name)||inv.helpers.isIP(v.name)){modal.querySelector('.iv-error').textContent='请输入有效域名，不包含协议、路径或 IP。';return;}if(Number(v.timeout)>=Number(v.interval)||!v.path.startsWith('/')){modal.querySelector('.iv-error').textContent='超时应小于检测间隔，请求路径以 / 开头。';return;}const key=id||'domain-'+Date.now();state.domains[key]={...d,...v,id:key,observation:{state:'未检测',dns:'未知',ips:[],http:null,certDays:null,chain:'未知',at:null,history:[]}};modal.close();persist('域名监控已保存，等待首次有效探测。');page='domains';domainDetail(key);});}
function domainProbe(id){const d=domainList().find(d=>d.id===id);if(!d)return;const mode=content.querySelector('#op-domain-result').value,prev=domainObservation(d),o={at:Date.now(),state:mode==='dns'?'DNS 异常':mode==='cert'?'证书即将到期':mode==='slow'?'响应慢':'正常',dns:mode==='dns'?'解析失败':'解析成功',ips:mode==='dns'?[]:['192.0.2.10'],ttl:mode==='dns'?null:300,dnsMs:mode==='dns'?null:8,http:mode==='dns'||d.protocol==='DNS'?null:Number(d.expected),httpMs:mode==='dns'||d.protocol==='DNS'?null:mode==='slow'?1500:43,certDays:d.protocol==='HTTPS'&&mode!=='dns'?(mode==='cert'?7:90):null,chain:d.protocol==='HTTPS'&&mode!=='dns'?'匹配 / 信任链通过（模拟）':'不适用 / 未知'};o.history=[{...o},...(prev.history||[])].slice(0,50);state.domains[id]={...d,observation:o};Object.values(state.rules).filter(r=>r.kind==='domains'&&r.target===id).forEach(r=>evaluateRule(r.key,r.metric==='dns'?(mode==='dns'?1:0):r.metric==='tls'?o.certDays:o.httpMs));persist('已记录域名模拟检测。');domainDetail(id);}
const archiveCache=new Map();
function trafficHosts(){return db().servers.filter(s=>asset(s.id)?.discovered);}
function getArchive(id,nic){const k=id+'/'+nic;if(archiveCache.has(k))return archiveCache.get(k);let data;try{data=JSON.parse(localStorage.getItem('infrascope.archive.'+k));}catch{}if(!data?.rows||!Array.isArray(data.rows)){const seeded=/^s[1-5]$/.test(id),a=asset(id),n=a?.interfaces.find(n=>n.id===nic),end=seeded?anchor:Math.floor(Date.now()/60000)*60000;data={version:1,origin:'SIMULATED',start:seeded?end-7*day:end,end,rows:seeded?C.generateArchive(end,n?.type==='bridge'?.25:id==='s2'?.3:1):[]};}archiveCache.set(k,data);return data;}
function storeArchive(){const data=getArchive(historyTarget,historyIface);try{localStorage.setItem('infrascope.archive.'+historyTarget+'/'+historyIface,JSON.stringify(data));feedback.textContent='所选接口的模拟历史已保存在本浏览器，刷新后可继续查询。';}catch{feedback.textContent='浏览器配额不足，历史仍保留在本次会话；可导出 CSV。';}}
function rangeBounds(range){const a=getArchive(historyTarget,historyIface);historyRange=range;historyTo=a.end;historyFrom=Math.max(a.start,historyTo-({'1h':3600000,'24h':day,'7d':7*day}[range]||day));}
function historyOptions(){const hs=trafficHosts();if(!hs.some(s=>s.id===historyTarget)){historyTarget=hs[0]?.id||'s1';historyIface=asset(historyTarget)?.interfaces[0]?.id||'eth0';}const a=asset(historyTarget);if(!a?.interfaces.some(n=>n.id===historyIface))historyIface=a?.interfaces[0]?.id||'eth0';return hs;}
function renderTraffic(){const hs=historyOptions(),s=db().servers.find(s=>s.id===historyTarget),a=asset(historyTarget),archive=getArchive(historyTarget,historyIface),rows=C.select(archive.rows,historyFrom,historyTo),sum=C.summarize(rows);content.innerHTML=pageHead('网络流量回溯','从异常时段追踪接口流量 · 按实际字节增量汇总',btn('导出所选 CSV','traffic-export')+btn('保存模拟历史','save-archive','','','main'))+`<section class="box"><div class="op-history-toolbar"><label>服务器<select id="op-history-host">${opts(hs.map(s=>[s.id,s.name]),historyTarget)}</select></label><label>网卡<select id="op-history-nic">${opts((a?.interfaces||[]).map(n=>[n.id,n.name+(a.monitor.includes(n.id)?' · 已监控':' · 未选监控')]),historyIface)}</select></label><div class="iv-tabs">${['1h','24h','7d'].map(r=>btn({'1h':'近 1 小时','24h':'近 24 小时','7d':'近 7 天'}[r],'range',r,'',historyRange===r?'selected':'')).join('')}</div></div><div class="op-history-toolbar"><label>开始时间（北京时间）<input type="datetime-local" id="op-from" value="${local(historyFrom)}"></label><label>结束时间（北京时间）<input type="datetime-local" id="op-to" value="${local(historyTo)}"></label>${btn('查询时段','query-range','','','main')}${btn('定位示例流量突增','peak-range')}${btn('接口告警规则','rules',historyTarget+'/'+historyIface,'traffic')}</div>${historyError?`<div class="iv-error" role="alert">${esc(historyError)}</div>`:''}<div class="iv-note">历史覆盖 ${dt(archive.start)} — ${dt(archive.end)} CST · 1 分钟模拟窗口 · 每个接口最多保存 7 天</div></section><div class="stats op-stat-space">${[['接收总流量',sum.valid?GiB(sum.rx):'—','只累计有效窗口'],['发送总流量',sum.valid?GiB(sum.tx):'—','收发分开，不叠加网桥'],['接收窗口峰值',sum.peakRx==null?'—':sum.peakRx.toFixed(2)+' Mbps','一分钟窗口平均值的峰值'],['样本完整率',historyTo>historyFrom?(sum.valid/Math.max(1,Math.floor((historyTo-historyFrom)/60000))*100).toFixed(2)+'%':'—',sum.valid+' 有效 / '+sum.missing+' 缺失 / '+Math.max(0,Math.floor((historyTo-historyFrom)/60000)-rows.length)+' 未覆盖']].map(([l,v,n])=>`<section class="box"><div class="stat-label">${l}</div><div class="value op-compact-value">${v}</div><div class="muted">${n}</div></section>`).join('')}</div>${box('所选时段 / 收发流量曲线',`<div class="op-chart-legend"><span>● 接收 Rx</span><span>● 发送 Tx</span><span>● 接收窗口峰值</span></div>${trafficChart(rows)}<div class="iv-note">曲线为分桶加权平均，虚线保留桶内分钟峰值。含缺失样本的桶断线，不补零。总量排除缺失窗口，不推算缺失流量。</div>`)}<div class="iv-summary">${box('峰值时段 · 点击进一步回看',table(['窗口结束 CST','接收 Mbps','发送 Mbps','回溯'],rows.filter(r=>r[1]!=null).sort((a,b)=>b[1]/b[3]-a[1]/a[3]).slice(0,6).map(r=>[dt(r[0]),(r[1]*8/r[3]/1000).toFixed(2),(r[2]*8/r[3]/1000).toFixed(2),btn('前后 15 分钟','zoom',String(r[0]))])))}${box('同一接口的关联告警',table(['事件','发生时间','操作'],state.events.filter(e=>e.kind==='traffic'&&e.target===historyTarget+'/'+historyIface&&e.at<=historyTo&&(e.resolved||Date.now())>=historyFrom).map(e=>[esc(e.title),dt(e.at),btn('查看事件','event',e.id)]))+`<div class="iv-callout">接口计数器可以回答“何时突增、持续多久、总量多少”。定位到具体客户端、会话或流向，需要后续接入 NetFlow / sFlow / IPFIX；此 Demo 未采集这些数据。</div>`)}</div>${box('记录与保留策略',`<div class="op-history-toolbar"><label>原始指标（正式后端规划）<select id="op-retain-raw"><option>1 秒 / 7 天</option><option>5 秒 / 7 天</option><option>5 秒 / 3 天</option></select></label><label>聚合指标（正式后端规划）<select id="op-retain-rollup"><option>1 分钟 / 90 天</option><option>1 分钟 / 30 天</option><option>5 分钟 / 180 天</option></select></label>${btn('保存策略草稿','retention')}</div><p class="iv-note">当前 Demo 实际数据是最多 7 天的一分钟模拟窗口，只有点击保存后持久化到本浏览器；不会在页面关闭后继续采集。正式系统应由 Rust Agent / Collector 与 PostgreSQL 连续记录。</p>`)} `;const p=state.policies[historyTarget+'/'+historyIface];if(p){content.querySelector('#op-retain-raw').value=p.raw;content.querySelector('#op-retain-rollup').value=p.rollup;}}
function trafficChart(rows){if(!rows.length)return '<div class="iv-empty">该时间范围没有历史数据。新接入设备不能回填未采集的过去流量。</div>';const points=C.bucket(rows),w=900,h=250,left=55,bottom=215,max=Math.max(1,...points.map(p=>p.peak||0))*1.15,start=rows[0][0]-rows[0][3],end=rows.at(-1)[0],x=t=>left+(t-start)/(end-start)*(w-left-15),y=v=>bottom-v/max*180;let svg=`<svg class="op-traffic-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="模拟历史流量，横轴北京时间，纵轴 Mbps；缺失数据断线"><text x="5" y="15">Mbps</text>`;for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${left}" x2="885" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${v.toFixed(0)}</text>`;}for(const [k,color]of[['peak','#c4b8f4'],['rx','#8072eb'],['tx','#44b79d']]){let d='',gap=true;for(const p of points){if(p[k]==null||p.missing){gap=true;continue;}d+=(gap?'M':'L')+x(p.time).toFixed(1)+','+y(p[k]).toFixed(1)+' ';gap=false;}svg+=`<path d="${d}" fill="none" stroke="${color}" stroke-width="${k==='peak'?1.5:2}" ${k==='peak'?'stroke-dasharray="4 3"':''}/>`;}for(let i=0;i<4;i++){const t=start+(end-start)*i/3;svg+=`<text x="${x(t)}" y="240" text-anchor="${i===0?'start':i===3?'end':'middle'}">${esc(new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}))}</text>`;}return svg+'</svg>';}
function openTraffic(id,nic,from,to){page='traffic';historyTarget=id;historyIface=nic||asset(id)?.monitor[0]||asset(id)?.interfaces[0]?.id;historyOptions();rangeBounds('24h');if(from!=null){historyFrom=from;historyTo=to;historyRange='custom';}historyError='';renderTraffic();}
function eventTraffic(id){const e=state.events.find(e=>e.id===id);if(!e)return;const [sid,nic]=e.target.split('/');openTraffic(sid,nic,e.at-15*60000,(e.resolved||e.at+30*60000)+15*60000);}
function bootstrap(){db().servers.forEach(s=>asset(s.id));if(!state.initialized){const rules=[newRule('devices','s8','heartbeat'),newRule('services','v4','failure'),newRule('domains','svc-v1','tls'),newRule('traffic','s1/eth0','rx')];rules.forEach(r=>state.rules[r.key]=r);const data=[['devices','s8','heartbeat','心跳超时，设备暂时失联','87 秒',anchor-87000,null,'严重'],['services','v4','failure','财务任务端口不可达','TCP 9090 · 连接拒绝',anchor-8*60000,null,'严重'],['domains','svc-v1','tls','办公门户证书即将到期','剩余 12 天',anchor-2*3600000,null,'警告'],['traffic','s1/eth0','rx','外网出口接收流量突增','分钟窗口峰值 358 Mbps',Date.parse('2026-10-17T14:30:00+08:00'),Date.parse('2026-10-17T14:56:00+08:00'),'警告']];state.events=data.map((v,i)=>{const [kind,target,metric,title,value,at,resolved,severity]=v,r=state.rules[kind+':'+target+':'+metric];r.runtime={bad:resolved?0:3,good:resolved?2:0,firing:!resolved,state:resolved?'正常':'告警中',since:resolved?null:at};return {id:'demo-event-'+i,rule:r.key,kind,target,targetName:r.targetName,business:r.business,severity,title,value,at,updated:resolved||at,resolved,ack:i===3,silencedUntil:null,channel:r.channel,receiver:r.receiver,delivery:'示例投递记录 · 未真实发送',timeline:[{at,text:'条件持续满足，创建模拟事件'},{at:at+1000,text:'生成模拟通知任务：'+r.channel},...(resolved?[{at:resolved,text:'新样本满足恢复条件'}]:[])]};});state.initialized=true;persist();}}
root.addEventListener('click',e=>{const b=e.target.closest('[data-op]');if(!b)return;const a=b.dataset.op,id=b.dataset.id,kind=b.dataset.kind;if(a==='close')root.querySelector('#op-dialog')?.close();else if(a==='rules')openRules(kind,id);else if(a==='evaluate')openEvaluate(id);else if(a==='alerts'){page='alerts';renderAlerts();}else if(a==='object-alerts'){page='alerts';alertQuery=id;alertKind='全部';alertState='全部';alertSeverity='全部';alertPeriod='全部';renderAlerts();}else if(a==='event'){page='alerts';eventDetail(id);}else if(a==='ack'||a==='silence'){const ev=state.events.find(e=>e.id===id);if(!ev)return;if(a==='ack'){ev.ack=true;ev.timeline.push({at:Date.now(),text:'操作员确认事件，故障状态不变'});}else{ev.silencedUntil=ev.silencedUntil>Date.now()?null:Date.now()+1800000;ev.timeline.push({at:Date.now(),text:ev.silencedUntil?'静默模拟通知 30 分钟':'取消静默'});}persist();eventDetail(id);}else if(a==='notify')root.querySelector('nav [data-page="notify"]').click();else if(a==='reset-filter'){alertQuery='';alertKind=alertSeverity=alertState=alertPeriod='全部';renderAlerts();}else if(a==='save-search'){const label=(alertQuery||kindLabel(alertKind))+' / '+alertState;state.savedSearches.unshift({label,query:alertQuery,kind:alertKind,severity:alertSeverity,state:alertState,period:alertPeriod});state.savedSearches=state.savedSearches.slice(0,5);persist();renderAlerts();}else if(a==='load-search'){const s=state.savedSearches[Number(id)];alertQuery=s.query;alertKind=s.kind;alertSeverity=s.severity;alertState=s.state;alertPeriod=s.period;renderAlerts();}else if(a==='domains'){page='domains';if(id&&domainList().some(d=>d.service===id))domainDetail('svc-'+id);else renderDomains();}else if(a==='domain'){page='domains';domainDetail(id);}else if(a==='add-domain')domainForm();else if(a==='edit-domain')domainForm(id);else if(a==='domain-probe')domainProbe(id);else if(a==='traffic')openTraffic(id,kind);else if(a==='event-traffic')eventTraffic(id);else if(a==='range'){rangeBounds(id);historyError='';renderTraffic();}else if(a==='query-range'){const from=Date.parse(content.querySelector('#op-from').value+':00+08:00'),to=Date.parse(content.querySelector('#op-to').value+':00+08:00');if(!Number.isFinite(from)||!Number.isFinite(to)||from>=to||to-from>7*day){historyError='请选择有效的起止时间，开始早于结束，跨度不超过 7 天。';}else{historyFrom=from;historyTo=to;historyRange='custom';historyError='';}renderTraffic();}else if(a==='zoom'){historyFrom=Number(id)-15*60000;historyTo=Number(id)+15*60000;historyRange='custom';renderTraffic();}else if(a==='peak-range'){historyFrom=Date.parse('2026-10-17T14:15:00+08:00');historyTo=Date.parse('2026-10-17T15:10:00+08:00');historyRange='custom';renderTraffic();}else if(a==='save-archive')storeArchive();else if(a==='traffic-export'){const ar=getArchive(historyTarget,historyIface),rows=C.select(ar.rows,historyFrom,historyTo);const blob=new Blob([C.csv(rows,names('devices',historyTarget)?.name||historyTarget,historyIface)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='SIMULATED-traffic-history.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(a==='retention'){state.policies[historyTarget+'/'+historyIface]={raw:content.querySelector('#op-retain-raw').value,rollup:content.querySelector('#op-retain-rollup').value};persist('记录策略草稿已保存；不会改变 Demo 历史分辨率或启动真实采集。');}else if(a==='discover'){const x=db().servers.find(s=>s.id===id),os=content.querySelector('#op-profile').value,prev=asset(id),at=Date.now();state.assets[id]=discoverData(x,os,at,{...prev,onlineSince:prev.sampledAt?prev.onlineSince:at,bootAt:prev.bootAt||at-2*day});Object.assign(x,{os,version:state.assets[id].version,cpu:x.cpu||8,ram:x.ram||16,disk:1152,state:'在线',cpuUse:42,memUse:61,age:'模拟上报'});inv.save('已载入模拟 Agent 资产。');persist();inv.render('devices',id);}else if(a==='save-ifaces'){const x=asset(id);x.mode=content.querySelector('#op-egress-mode').value;x.monitor=x.mode==='auto'?C.egress(x.interfaces):[...content.querySelectorAll('[data-op-nic]:checked')].map(i=>i.dataset.opNic);persist('已保存接口监控选择。');inv.render('devices',id);}else if(a==='scenario'){const x=asset(id),m=content.querySelector('#op-scenario').value,at=Date.now();x.status={online:'在线',lost:'失联 / 原因未知',network:'断网（证据确认）',off:'已关机（电源确认）'}[m];x.reason={online:'Agent 心跳有效（模拟）',lost:'未收到心跳；电源、链路状态未知',network:'带外确认电源开启 + 交换机链路 Down（模拟）',off:'虚拟化平台 / 带外电源状态 Off（模拟）'}[m];x.stateAt=at;if(m==='online'){if(x.poweredOff||!x.bootAt)x.bootAt=at;x.poweredOff=false;x.sampledAt=at;x.onlineSince=at;}else{x.onlineSince=null;if(m==='off')x.poweredOff=true;}db().servers.find(s=>s.id===id).state=x.status;inv.save('已切换模拟状态。');Object.values(state.rules).filter(r=>r.kind==='devices'&&r.target===id&&r.metric==='heartbeat').forEach(r=>evaluateRule(r.key,m==='online'?0:90));persist();inv.render('devices',id);}else if(a==='service-state'){const x=db().services.find(s=>s.id===id),mode=content.querySelector('#op-service-scenario').value,at=Date.now(),latency=mode==='slow'?1500:mode==='down'?null:43;state.assets['service:'+id]={status:mode==='slow'?'响应慢':mode==='down'?'端口不可达':'正常',at,availableSince:mode==='ok'?at:mode==='slow'?(state.assets['service:'+id]?.availableSince||at):null,latency};x.state=mode==='down'?'异常':mode==='slow'?'响应慢':'正常';x.latency=latency;x.code=mode==='down'?'连接拒绝':x.protocol==='TCP'?'连接成功':String(x.expected);x.checked=dt(at);Object.values(state.rules).filter(r=>r.kind==='services'&&r.target===id).forEach(r=>evaluateRule(r.key,r.metric==='latency'?latency:mode==='down'?1:0));inv.save('服务模拟状态已更新。');persist();inv.render('services',id);}else if(a==='from-port'){const s=db().servers.find(s=>s.id===id),port=Number(kind),exists=db().services.find(v=>v.target===id&&Number(v.listen)===port);if(exists){inv.render('services',exists.id);return;}const v={id:'discovered-'+Date.now(),name:s.name+':'+port,business:s.business,target:id,protocol:'TCP',listen:port,port,domain:s.ip,path:'',expected:'',interval:10,timeout:3,fail:3,recover:2,collector:'机房 A · collector-01',state:'未检测',code:'',latency:null,checked:null,history:[],streak:0,healthyStreak:0};db().services.push(v);inv.save('已从监听端口创建服务监控草稿；尚未证明端口可达。');inv.render('services',v.id);}});
root.addEventListener('input',e=>{if(e.target.id==='op-alert-search'){alertQuery=e.target.value;paintEvents();}});
root.addEventListener('change',e=>{const id=e.target.id;if(id.startsWith('op-alert-')){if(id==='op-alert-kind')alertKind=e.target.value;if(id==='op-alert-state')alertState=e.target.value;if(id==='op-alert-severity')alertSeverity=e.target.value;if(id==='op-alert-period')alertPeriod=e.target.value;paintEvents();}if(id==='op-egress-mode'){const auto=e.target.value==='auto';content.querySelectorAll('[data-op-nic]').forEach(n=>n.disabled=auto);}if(id==='op-history-host'){historyTarget=e.target.value;historyIface=asset(historyTarget).monitor[0]||asset(historyTarget).interfaces[0].id;rangeBounds('24h');renderTraffic();}if(id==='op-history-nic'){historyIface=e.target.value;rangeBounds('24h');renderTraffic();}});
bootstrap();window.InfraOps={render,rowStatus,ruleButton,detailTop,detailBottom,onConfigured,onProbe,openTraffic,asset,events:()=>state.events,rules:()=>state.rules,persist};
const entry=location.hash.slice(1);if(['alerts','domains','traffic'].includes(entry))window.addEventListener('load',()=>root.querySelector('nav [data-page="'+entry+'"]').click(),{once:true});
})();
